-- Generated from the checked-in product fallbacks.
-- After this initial seed, Supabase is the runtime source of truth.
do $migration$
declare
  catalog jsonb := $catalog$[{"id":"upledger","slug":"upledger","name":"UpLedger","tagline":"Tus finanzas claras, privadas y bajo control.","tagline_en":"Clear, private finances under your control.","shortDescription":"Registra movimientos, organiza cuentas y presupuestos, revisa tu patrimonio y toma decisiones con previsiones privadas.","shortDescription_en":"Track transactions, organize accounts and budgets, review your net worth, and plan ahead with private forecasts.","longDescription":"UpLedger convierte las finanzas personales en un sistema claro: cuentas, movimientos, presupuestos, patrimonio y previsiones en una experiencia diseñada para iPhone y iPad.","longDescription_en":"UpLedger turns personal finances into a clear system: accounts, transactions, budgets, net worth, and forecasts in an experience designed for iPhone and iPad.","problem":"Las hojas de cálculo y las apps que monetizan los datos convierten una tarea cotidiana en algo disperso, lento y poco confiable.","problem_en":"Spreadsheets and data-hungry apps turn an everyday task into a fragmented, slow, and untrustworthy experience.","benefits":["Claridad diaria: entiende ingresos, gastos, cuentas y presupuestos desde una vista útil.","Decisiones con contexto: revisa patrimonio y previsiones antes de comprometerte.","Privacidad por diseño: tus registros se guardan en el dispositivo y en tu iCloud privado si activas sincronización."],"benefits_en":["Daily clarity: understand income, expenses, accounts, and budgets from one useful view.","Decisions with context: review net worth and forecasts before you commit.","Privacy by design: records stay on-device and in your private iCloud when sync is enabled."],"features":["Movimientos y borradores: registra, revisa y confirma gastos e ingresos con control.","Cuentas y presupuestos: organiza tu dinero por categorías y detecta desviaciones.","Patrimonio y previsiones: entiende evolución, compromisos recurrentes y escenarios futuros.","Automatización opcional: reglas, dictado y asistencia inteligente con controles explícitos.","Ecosistema Apple: iPhone, iPad, widgets, atajos y sincronización privada opcional."],"features_en":["Transactions and drafts: record, review, and confirm expenses and income with control.","Accounts and budgets: organize money by category and spot deviations.","Net worth and forecasts: understand trends, recurring commitments, and future scenarios.","Optional automation: rules, dictation, and intelligent assistance with explicit controls.","Apple ecosystem: iPhone, iPad, widgets, shortcuts, and optional private sync."],"audience":"Personas que quieren gestionar sus finanzas personales sin publicidad, sin vender sus datos y sin perder tiempo en hojas de cálculo.","audience_en":"People who want to manage personal finances without ads, selling their data, or losing time in spreadsheets.","status":"coming_soon","featured":true,"category":"Finanzas","platform":["iOS","iPadOS"],"supportEmail":"romerodev.app@gmail.com","iconUrl":"assets/images/upledger/upledger-icon.svg","coverImageUrl":"assets/images/upledger/upledger-hero.png","screenshots":["Resumen","Facturas","Capturar","Plan","Libro","Tendencias","Hogar","Cuentas","Detalle","Ajustes"],"primaryCtaLabel":"Próximamente en App Store","primaryCtaLabel_en":"Coming soon on the App Store","primaryCtaUrl":"/es/casos/upledger/soporte/","secondaryCtaLabel":"Centro de soporte","secondaryCtaLabel_en":"Support center","secondaryCtaUrl":"/es/casos/upledger/soporte/","colorPrimary":"#2563eb","colorSecondary":"#14b8a6","updatedAt":"2026-08-02","seo":{"title":"UpLedger: finanzas personales privadas y claras | RomeroDev","description":"Gestiona cuentas, gastos, presupuestos, patrimonio y previsiones desde iPhone o iPad con UpLedger."},"pricing":[{"name":"Mensual","name_en":"Monthly","price":"4,99 €","cadence":"/mes","cadence_en":"/month","description":"7 días de prueba para cuentas elegibles; renovación mensual.","description_en":"7-day trial for eligible accounts; monthly renewal.","badge":"Prueba de 7 días","badge_en":"7-day trial","isIndicative":true},{"name":"Anual","name_en":"Annual","price":"34,99 €","cadence":"/año","cadence_en":"/year","description":"7 días de prueba para cuentas elegibles; el mejor valor anual.","description_en":"7-day trial for eligible accounts; best annual value.","badge":"Mejor valor","badge_en":"Best value","featured":true,"isIndicative":true}],"freeFeatures":["Cuentas y movimientos","Categorías y presupuestos","Patrimonio básico","Datos locales y exportación"],"freeFeatures_en":["Accounts and transactions","Categories and budgets","Basic net worth","Local data and export"],"proFeatures":["Previsiones y escenarios","Reglas y automatizaciones","Análisis avanzado","Funciones Pro futuras incluidas"],"proFeatures_en":["Forecasts and scenarios","Rules and automations","Advanced analysis","Included future Pro features"],"faq":[{"question":"¿UpLedger conecta con mi banco?","question_en":"Does UpLedger connect to my bank?","answer":"La primera versión se centra en el registro y control directo de tus finanzas. No solicita credenciales bancarias ni vende datos financieros.","answer_en":"The first version focuses on direct financial tracking and control. It does not request bank credentials or sell financial data."},{"question":"¿Dónde se guardan mis datos?","question_en":"Where is my data stored?","answer":"Los datos se guardan localmente en tu dispositivo. Si activas la sincronización, se utiliza tu contenedor privado de iCloud.","answer_en":"Data is stored locally on your device. If you enable sync, it uses your private iCloud container."},{"question":"¿Cómo funciona UpLedger Pro?","question_en":"How does UpLedger Pro work?","answer":"Pro ofrece suscripción mensual o anual. Apple muestra el precio final, impuestos, prueba disponible y condiciones antes de confirmar.","answer_en":"Pro offers monthly or annual subscriptions. Apple displays the final price, taxes, available trial, and terms before confirmation."},{"question":"¿Puedo cancelar cuando quiera?","question_en":"Can I cancel anytime?","answer":"Sí. Gestiona o cancela la suscripción desde Ajustes > tu nombre > Suscripciones. Eliminar la app no cancela la suscripción.","answer_en":"Yes. Manage or cancel from Settings > your name > Subscriptions. Deleting the app does not cancel a subscription."}],"legal":{"privacy":{"title":"Política de privacidad de UpLedger","title_en":"UpLedger Privacy Policy","updatedAt":"2026-08-02","body":["## 1. Responsable","Responsable: Lester Romero Bernardo (RomeroDev), Calle Madre Juana María Condesa Lluch 6, Valencia, España. Contacto de privacidad: romerodev.app@gmail.com.","## 2. Datos y finalidad","UpLedger almacena cuentas, movimientos, categorías, presupuestos, previsiones, preferencias y borradores para prestar las funciones de gestión financiera. No utiliza los datos financieros para publicidad ni los vende.","## 3. Almacenamiento y sincronización","Los datos se almacenan localmente mediante SwiftData. Si activas la sincronización, se usa el contenedor privado de iCloud asociado a tu Apple ID. Puedes eliminar datos desde la app o desinstalándola.","## 4. Proveedores opcionales","Apple procesa las compras con StoreKit. RevenueCat gestiona técnicamente el estado de la suscripción y no recibe movimientos ni saldos. Si activas Diagnósticos y uso, Firebase Analytics y Crashlytics reciben eventos técnicos y fallos agregados, nunca movimientos, importes, comercios, texto capturado, correo ni saldos.","## 5. IA y servicios externos","La asistencia inteligente local no transmite tus registros. Si configuras un proveedor de IA propio, UpLedger pide consentimiento antes de enviar el texto necesario a ese proveedor. Los tipos de cambio e inflación pueden consultar servicios públicos para la divisa o país solicitado, sin enviar tu historial financiero.","## 6. Permisos","Micrófono y reconocimiento de voz se solicitan para dictado; biometría para el bloqueo local; notificaciones para alertas; y los permisos solo se usan al activar la función correspondiente.","## 7. Derechos y contacto","Puedes solicitar acceso, rectificación, supresión, limitación, oposición, portabilidad o retirada del consentimiento escribiendo a romerodev.app@gmail.com. También puedes reclamar ante la autoridad competente."],"body_en":["## 1. Controller","Controller: Lester Romero Bernardo (RomeroDev), Calle Madre Juana María Condesa Lluch 6, Valencia, Spain. Privacy contact: romerodev.app@gmail.com.","## 2. Data and purpose","UpLedger stores accounts, transactions, categories, budgets, forecasts, preferences, and drafts to provide personal-finance features. It does not use financial data for advertising or sell it.","## 3. Storage and sync","Data is stored locally through SwiftData. If you enable sync, UpLedger uses the private iCloud container associated with your Apple ID. You can delete data in the app or by uninstalling it.","## 4. Optional providers","Apple processes purchases through StoreKit. RevenueCat technically manages subscription status and does not receive transactions or balances. If you enable Diagnostics and usage, Firebase Analytics and Crashlytics receive aggregated technical events and crashes, never transactions, amounts, merchants, captured text, email, or balances.","## 5. AI and external services","Local intelligent assistance does not transmit records. If you configure your own AI provider, UpLedger asks for consent before sending the text needed to that provider. Exchange rates and inflation may query public services for the requested currency or country without sending your financial history.","## 6. Permissions","Microphone and speech recognition are requested for dictation; biometrics for local lock; notifications for alerts; and every permission is used only when you enable its related feature.","## 7. Rights and contact","You can request access, rectification, erasure, restriction, objection, portability, or withdraw consent by writing to romerodev.app@gmail.com. You may also complain to the competent authority."]},"terms":{"title":"Términos de uso de UpLedger","title_en":"UpLedger Terms of Use","updatedAt":"2026-08-02","body":["## 1. Aceptación","Al instalar o utilizar UpLedger aceptas estos términos y la Política de privacidad.","## 2. Naturaleza del servicio","UpLedger es una herramienta de organización financiera personal. No presta asesoramiento financiero, fiscal, contable, legal ni de inversión, y no sustituye a un profesional cualificado.","## 3. Uso responsable","Eres responsable de revisar la información introducida, proteger tu dispositivo y Apple ID y utilizar la app de forma lícita. No debes intentar acceder a sistemas ajenos, eludir medidas de seguridad ni introducir datos de terceros sin autorización.","## 4. Exactitud y disponibilidad","Los cálculos, categorías, previsiones y sugerencias son informativos y pueden contener errores o depender de datos incompletos. Verifica cualquier decisión económica relevante. No garantizamos disponibilidad ininterrumpida de servicios de Apple o terceros.","## 5. Propiedad intelectual","UpLedger, su código, marca, diseño y materiales propios pertenecen a Lester Romero Bernardo (RomeroDev) o a sus licenciantes. Se concede una licencia personal, limitada, revocable y no transferible para usar la app conforme a estos términos.","## 6. Compras","Las funciones Pro se procesan mediante Apple y se rigen además por las Condiciones de suscripción publicadas en esta web y la información mostrada por App Store antes de comprar.","## 7. Legislación y contacto","Se aplica la legislación española, sin perjuicio de los derechos imperativos del consumidor. Contacto: romerodev.app@gmail.com."],"body_en":["## 1. Acceptance","By installing or using UpLedger, you accept these terms and the Privacy Policy.","## 2. Nature of the service","UpLedger is a personal-finance organization tool. It does not provide financial, tax, accounting, legal, or investment advice and does not replace a qualified professional.","## 3. Responsible use","You are responsible for reviewing entered information, protecting your device and Apple ID, and using the app lawfully. You must not attempt to access third-party systems, circumvent security measures, or enter third-party data without authorization.","## 4. Accuracy and availability","Calculations, categories, forecasts, and suggestions are informational and may be inaccurate or depend on incomplete data. Verify any relevant financial decision. We do not guarantee uninterrupted availability of Apple or third-party services.","## 5. Intellectual property","UpLedger, its code, brand, design, and own materials belong to Lester Romero Bernardo (RomeroDev) or its licensors. You receive a personal, limited, revocable, non-transferable license to use the app under these terms.","## 6. Purchases","Pro features are processed by Apple and are also governed by the Subscription Terms published on this website and the information the App Store displays before purchase.","## 7. Law and contact","Spanish law applies, without prejudice to mandatory consumer rights. Contact: romerodev.app@gmail.com."]},"subscriptions":{"title":"Condiciones de suscripción de UpLedger Pro","title_en":"UpLedger Pro Subscription Terms","updatedAt":"2026-08-02","body":["## 1. Planes","UpLedger Pro ofrece planes mensual y anual. La versión gratuita puede utilizarse sin contratar una suscripción.","## 2. Precio, facturación y prueba","Apple procesa el pago y muestra antes de confirmar el precio final, impuestos, moneda, duración y cualquier prueba u oferta disponible. El plan mensual cuesta 4,99 € y el anual 34,99 € como precio base en España; los importes pueden variar por territorio. Las cuentas elegibles pueden recibir una prueba gratuita de 7 días.","## 3. Renovación automática","La suscripción se renueva automáticamente salvo cancelación al menos 24 horas antes del final del periodo. El cobro se realiza a tu Apple ID. Gestiona o cancela desde Ajustes > tu nombre > Suscripciones. Eliminar la app no cancela la suscripción.","## 4. Restauración y acceso","Puedes restaurar compras realizadas con el mismo Apple ID desde UpLedger. Al finalizar el periodo pagado, se desactivan las funciones Pro; tus datos no se eliminan automáticamente.","## 5. Cambios y reembolsos","Apple puede aplicar cambios de precio y los comunicará conforme a sus reglas. Apple gestiona cancelaciones y solicitudes de reembolso mediante reportaproblem.apple.com.","## 6. Contacto","Soporte y consultas de suscripción: romerodev.app@gmail.com."],"body_en":["## 1. Plans","UpLedger Pro offers monthly and annual plans. The free version can be used without a subscription.","## 2. Price, billing, and trial","Apple processes payment and displays the final price, taxes, currency, duration, and any available trial or offer before confirmation. The monthly plan is €4.99 and the annual plan is €34.99 as base prices in Spain; amounts may vary by territory. Eligible accounts may receive a 7-day free trial.","## 3. Automatic renewal","The subscription renews automatically unless canceled at least 24 hours before the period ends. Charges are made to your Apple ID. Manage or cancel in Settings > your name > Subscriptions. Deleting the app does not cancel the subscription.","## 4. Restore and access","You can restore purchases made with the same Apple ID from UpLedger. When a paid period ends, Pro features are disabled; your data is not automatically deleted.","## 5. Changes and refunds","Apple may apply price changes and notify you under its rules. Apple manages cancellations and refund requests at reportaproblem.apple.com.","## 6. Contact","Subscription support and questions: romerodev.app@gmail.com."]}}}]$catalog$::jsonb;
  product jsonb;
  product_id uuid;
  faq_item jsonb;
  legal_item jsonb;
  faq_order integer;
begin
  for product in select value from jsonb_array_elements(catalog)
  loop
    insert into public.apps (
      slug, name, tagline, tagline_en, short_description, short_description_en,
      long_description, long_description_en, problem, problem_en, benefits,
      benefits_en, features, features_en, audience, audience_en, status,
      featured, category, platform, app_store_url, website_url, support_email,
      icon_url, cover_image_url, screenshots, video_url, primary_cta_label,
      primary_cta_label_en, primary_cta_url, secondary_cta_label,
      secondary_cta_label_en, secondary_cta_url, color_primary, color_secondary,
      seo_title, seo_description, seo_image, pricing, free_features,
      free_features_en, pro_features, pro_features_en, published_at, updated_at
    ) values (
      product->>'slug', product->>'name', product->>'tagline', product->>'tagline_en',
      product->>'shortDescription', product->>'shortDescription_en',
      product->>'longDescription', product->>'longDescription_en',
      product->>'problem', product->>'problem_en',
      array(select jsonb_array_elements_text(coalesce(product->'benefits', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'benefits_en', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'features', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'features_en', '[]'::jsonb))),
      product->>'audience', product->>'audience_en', product->>'status',
      coalesce((product->>'featured')::boolean, false), product->>'category',
      array(select jsonb_array_elements_text(coalesce(product->'platform', '[]'::jsonb))),
      nullif(product->>'appStoreUrl', ''), nullif(product->>'websiteUrl', ''),
      product->>'supportEmail', nullif(product->>'iconUrl', ''),
      nullif(product->>'coverImageUrl', ''),
      array(select jsonb_array_elements_text(coalesce(product->'screenshots', '[]'::jsonb))),
      nullif(product->>'videoUrl', ''), product->>'primaryCtaLabel',
      nullif(product->>'primaryCtaLabel_en', ''), product->>'primaryCtaUrl',
      nullif(product->>'secondaryCtaLabel', ''), nullif(product->>'secondaryCtaLabel_en', ''),
      nullif(product->>'secondaryCtaUrl', ''), nullif(product->>'colorPrimary', ''),
      nullif(product->>'colorSecondary', ''), product#>>'{seo,title}',
      product#>>'{seo,description}', nullif(product#>>'{seo,image}', ''),
      coalesce(product->'pricing', '[]'::jsonb),
      array(select jsonb_array_elements_text(coalesce(product->'freeFeatures', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'freeFeatures_en', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'proFeatures', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'proFeatures_en', '[]'::jsonb))),
      nullif(product->>'publishedAt', '')::timestamptz, now()
    )
    on conflict (slug) do update set
      name = excluded.name, tagline = excluded.tagline, tagline_en = excluded.tagline_en,
      short_description = excluded.short_description, short_description_en = excluded.short_description_en,
      long_description = excluded.long_description, long_description_en = excluded.long_description_en,
      problem = excluded.problem, problem_en = excluded.problem_en, benefits = excluded.benefits,
      benefits_en = excluded.benefits_en, features = excluded.features, features_en = excluded.features_en,
      audience = excluded.audience, audience_en = excluded.audience_en, status = excluded.status,
      featured = excluded.featured, category = excluded.category, platform = excluded.platform,
      app_store_url = excluded.app_store_url, website_url = excluded.website_url,
      support_email = excluded.support_email, icon_url = excluded.icon_url,
      cover_image_url = excluded.cover_image_url, screenshots = excluded.screenshots,
      video_url = excluded.video_url, primary_cta_label = excluded.primary_cta_label,
      primary_cta_label_en = excluded.primary_cta_label_en, primary_cta_url = excluded.primary_cta_url,
      secondary_cta_label = excluded.secondary_cta_label,
      secondary_cta_label_en = excluded.secondary_cta_label_en,
      secondary_cta_url = excluded.secondary_cta_url, color_primary = excluded.color_primary,
      color_secondary = excluded.color_secondary, seo_title = excluded.seo_title,
      seo_description = excluded.seo_description, seo_image = excluded.seo_image,
      pricing = excluded.pricing, free_features = excluded.free_features,
      free_features_en = excluded.free_features_en, pro_features = excluded.pro_features,
      pro_features_en = excluded.pro_features_en, published_at = excluded.published_at,
      updated_at = now()
    returning id into product_id;

    delete from public.app_faqs where app_id = product_id;
    faq_order := 0;
    for faq_item in select value from jsonb_array_elements(coalesce(product->'faq', '[]'::jsonb))
    loop
      insert into public.app_faqs (app_id, question, question_en, answer, answer_en, sort_order)
      values (
        product_id, faq_item->>'question', nullif(faq_item->>'question_en', ''),
        faq_item->>'answer', nullif(faq_item->>'answer_en', ''), faq_order
      );
      faq_order := faq_order + 1;
    end loop;

    delete from public.app_legal_pages where app_id = product_id;
    for legal_item in
      select value from jsonb_array_elements(jsonb_build_array(
        jsonb_build_object('kind', 'privacy', 'page', product#>'{legal,privacy}'),
        jsonb_build_object('kind', 'terms', 'page', product#>'{legal,terms}'),
        jsonb_build_object('kind', 'subscriptions', 'page', product#>'{legal,subscriptions}')
      ))
    loop
      if legal_item->'page' is not null and legal_item->'page' <> 'null'::jsonb then
        insert into public.app_legal_pages (app_id, kind, title, title_en, body, body_en, updated_at)
        values (
          product_id, legal_item->>'kind', legal_item#>>'{page,title}',
          nullif(legal_item#>>'{page,title_en}', ''),
          array_to_string(array(select jsonb_array_elements_text(coalesce(legal_item#>'{page,body}', '[]'::jsonb))), E'\n'),
          array_to_string(array(select jsonb_array_elements_text(coalesce(legal_item#>'{page,body_en}', '[]'::jsonb))), E'\n'),
          coalesce(nullif(legal_item#>>'{page,updatedAt}', '')::timestamptz, now())
        );
      end if;
    end loop;
  end loop;
end
$migration$;
